-- Catálogo central de reglas de juego (DEV/demo con créditos simulados).
CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE IF NOT EXISTS reglas_juego (
 id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
 codigo varchar(80) NOT NULL UNIQUE, nombre varchar(120) NOT NULL, categoria varchar(60) NOT NULL, ejemplo varchar(220) NOT NULL,
 usa_cantidad boolean NOT NULL DEFAULT false, cantidad_min integer, cantidad_max integer,
 permite_exactamente boolean NOT NULL DEFAULT true, permite_mas boolean NOT NULL DEFAULT true, permite_menos boolean NOT NULL DEFAULT true,
 mostrar_sala boolean NOT NULL DEFAULT true, mostrar_casa boolean NOT NULL DEFAULT true, activa boolean NOT NULL DEFAULT true,
 fuente_validacion varchar(20) NOT NULL DEFAULT 'RESULTADO' CHECK (fuente_validacion IN ('RESULTADO','EVENTOS','ESTADISTICAS')),
 configuracion jsonb NOT NULL DEFAULT '{}'::jsonb, orden integer NOT NULL DEFAULT 1000, creado_por uuid REFERENCES usuarios(id),
 creado_en timestamptz NOT NULL DEFAULT now(), actualizado_en timestamptz NOT NULL DEFAULT now(),
 CHECK (cantidad_min IS NULL OR cantidad_max IS NULL OR cantidad_min <= cantidad_max)
);
CREATE INDEX IF NOT EXISTS ix_reglas_juego_destino ON reglas_juego(activa, mostrar_sala, mostrar_casa, categoria);

ON CONFLICT (codigo) DO UPDATE SET nombre=EXCLUDED.nombre,categoria=EXCLUDED.categoria,ejemplo=EXCLUDED.ejemplo,usa_cantidad=EXCLUDED.usa_cantidad,fuente_validacion=EXCLUDED.fuente_validacion,orden=EXCLUDED.orden;
